export function mountTrustedIntake(root,{operator,api}){
 const host=root.querySelector('.connections-content, .connection-grid, main')||root;
 const card=document.createElement('section');
 card.className='trusted-intake-card';
 card.innerHTML=`<div class="trusted-intake-heading"><div><span class="eyebrow">AUTOMATED CASE INTAKE</span><h2>From paid purchase to a case, automatically.</h2><p>Your store sends the learner and course mapping. PayTrace checks the PayPal sandbox order itself before opening a case. No access is granted by intake.</p></div><span class="trusted-intake-badge">Store server → PayPal check → case</span></div><div class="trusted-intake-status" role="status">${operator?'Checking store connection…':'Unlock merchant controls to configure a private store key.'}</div><div class="trusted-intake-actions"><button type="button" class="trusted-intake-rotate" ${operator?'':'disabled'}>Create store key</button><a href="store-demo.html">Run demo store checkout ↗</a><a href="https://github.com/sagitta414/paytrace-recover/blob/feature/access-assurance/docs/TRUSTED-STORE-INTAKE.md" target="_blank" rel="noopener noreferrer">Integration guide ↗</a></div><div class="trusted-intake-key" hidden><label for="store-intake-token">Copy this key now. It is shown once.</label><div><input id="store-intake-token" type="text" readonly autocomplete="off"><button type="button" class="trusted-intake-copy">Copy</button></div><small>Keep it on your store server. Rotating revokes the previous key immediately.</small></div>`;
 host.append(card);
 if(!operator)return;
 const status=card.querySelector('.trusted-intake-status'),button=card.querySelector('.trusted-intake-rotate'),keyBox=card.querySelector('.trusted-intake-key'),keyInput=card.querySelector('#store-intake-token');
 api('intake/key').then(result=>{if(!card.isConnected)return;status.textContent=result.configured?'Store key active. The store can send sandbox purchases for verification.':'No store key yet. Create one when your store server is ready.';button.textContent=result.configured?'Rotate store key':'Create store key';}).catch(e=>{if(card.isConnected)status.textContent=e.message||'Store connection status is unavailable.';});
 button.onclick=async()=>{button.disabled=true;status.textContent='Saving a new store key…';keyBox.hidden=true;try{const result=await api('intake/key',{});keyInput.value=result.key;keyBox.hidden=false;button.textContent='Rotate store key';status.textContent='Store key created. Copy it to your store server; the previous key, if any, is revoked.';}catch(e){status.textContent=e.message||'Could not create the store key.';}finally{button.disabled=false;}};
 card.querySelector('.trusted-intake-copy').onclick=async()=>{try{await navigator.clipboard.writeText(keyInput.value);status.textContent='Key copied. Store it only in your server environment.';}catch{keyInput.select();status.textContent='Select and copy the key manually.';}};
}
